  ($d$qwen/qwen3-omni-30b-a3b$d$::text, '6b6eb098782c'::text, $d$Qwen3 Omni 30B A3B is the Qwen team's natively omni-modal mixture-of-experts model, which understands text, images, audio and video and responds with text and natural speech.$d$::text),
  ($d$qwen/qwen3-omni-30b-a3b-captioner$d$::text, '56509e9941a3'::text, $d$Qwen 3 Omni 30B A3B Captioner is a version of Qwen3-Omni fine-tuned to produce detailed captions of audio input, including speech, sound and music.$d$::text),
