  ($d$topaz/proteus$d$::text, null::text, $d$Proteus is Topaz Labs' video enhancement model for upscaling and restoring video.$d$::text),
  ($d$topaz/starlight-precise-2.6$d$::text, null::text, $d$Starlight Precise 2.6 is a version of Topaz Labs' Starlight video restoration and upscaling model.$d$::text),
  ($d$topaz/wonder-3.5$d$::text, null::text, $d$Wonder 3.5 is Topaz Labs' image upscaling and enhancement model.$d$::text),
  ($d$typesafe/jev-1.14.0$d$::text, '6bc69243f26d'::text, $d$Jev 1.14 is TypeSafe's decision model, which evaluates text, structured records, and images and returns probabilities, choices, scores, and bounding boxes. Image input, box answers and long context are experimental.$d$::text),
  ($d$undi95/remm-slerp-l2-13b$d$::text, '8602b9b2b64b'::text, $d$ReMM SLERP L2 13B is a recreation of the original MythoMax-L2-13B merge using updated models.$d$::text),
  ($d$xiaomi/mimo-v2.5$d$::text, 'c41003b9f70d'::text, $d$MiMo V2.5 is a native omnimodal model by Xiaomi that accepts text, image, video and audio input and produces text.$d$::text),
  ($d$z-ai/autoglm-phone-9b-multilingual$d$::text, '7711a9567f91'::text, $d$AutoGLM Phone 9B Multilingual is Z.ai's multilingual 9B phone-agent model, built on AutoGLM, that understands smartphone screens and executes operations to complete tasks.$d$::text),
  ($d$z-ai/glm-4-9b$d$::text, '46b74d1c0c4b'::text, $d$GLM 4 9B is an open-weight 9B-parameter model from Z.ai's GLM-4 series.$d$::text),
  ($d$z-ai/glm-4-9b-2024-06-04$d$::text, '46b74d1c0c4b'::text, $d$GLM 4 9B (2024-06-04) is the June 2024 release of Z.ai's open-weight 9B-parameter GLM-4 model.$d$::text),
  ($d$z-ai/glm-4-9b-chat$d$::text, '46b74d1c0c4b'::text, $d$GLM 4 9B Chat is the chat version of Z.ai's open-weight 9B-parameter GLM-4 model.$d$::text),
  ($d$z-ai/glm-4-9b-chat-1m$d$::text, '46b74d1c0c4b'::text, $d$GLM 4 9B Chat 1M is a long-context version of Z.ai's open-weight GLM-4 9B Chat model, with a context window of about 1 million tokens.$d$::text),
  ($d$z-ai/glm-4.1v-9b$d$::text, '46b74d1c0c4b'::text, $d$GLM 4.1V 9B is Z.ai's open-weight 9B-parameter vision-language model from the GLM-4.1V series.$d$::text),
  ($d$z-ai/glm-4.5-x$d$::text, '46b74d1c0c4b'::text, $d$GLM 4.5 X is a faster-serving version of Z.ai's GLM-4.5 model.$d$::text),
  ($d$z-ai/glm-4.6v-flash$d$::text, 'cc1d702a4924'::text, $d$GLM 4.6V Flash is Z.ai's lightweight vision-language model from the GLM-4.6V series. It is tuned for lower latency and cost-sensitive production use.$d$::text),
  ($d$z-ai/glm-4v-9b$d$::text, '46b74d1c0c4b'::text, $d$GLM 4V 9B is Z.ai's open-weight 9B-parameter vision-language model from the GLM-4 series.$d$::text),
  ($d$z-ai/glm-5.3-fast$d$::text, null::text, $d$GLM 5.3 Fast is a faster-serving version of Z.AI's GLM 5.3 model.$d$::text),
  ($d$z-ai/glm-5v-turbo$d$::text, 'f774780fea87'::text, $d$GLM 5V Turbo is Z.ai's first native multimodal agent foundation model, built for vision-based coding and agent-driven tasks. It accepts text, image and video input and produces text.$d$::text)
), applied as (
  update public.v2_models m
  set description = f.new_description,
      updated_at = now()
  from fixes f
  where m.model_slug = f.model_slug
    and case
      when f.old_description_md5 is null then m.description is null
      else left(md5(m.description), 12) = f.old_description_md5
    end
  returning m.model_slug
)
select count(*) as updated_rows, 388 as expected_rows from applied;
